x = [1 2 3 4 5 6 7 8];
max(abs(ifft(fft(x)) - x))
Y = fft(x);
Y(4:6) = 0;                 % zero some bins
xf = ifft(Y, 'symmetric');
isreal(xf)

I = zeros(64);
I(20:44, 28:36) = 1;
F = fft2(I);
S = fftshift(log(1 + abs(F)));
imagesc(S); axis image; colormap gray

I = double(magic(32));
F = fft2(I);
[R, C] = size(F);
mask = false(R, C);
mask(1:4, 1:4) = true;
mask = mask | flipud(circshift(mask, [1 0]));
Ilow = ifft2(F .* mask, 'symmetric');
imagesc(Ilow); axis image

V = rand(8, 8, 8);
F = fftn(V);
size(F)
max(abs(ifftn(F) - V), [], 'all')
Fp = fftn(V, [16 16 16]);
size(Fp)

A = rand(16, 16, 16);
K = zeros(16, 16, 16);
K(1:3, 1:3, 1:3) = 1/27;
C = ifftn(fftn(A) .* fftn(K), 'symmetric');
size(C)

