I = double(magic(8));
k = ones(3)/9;
smoothed = conv2(I, k, 'same');
u = [1 2 1]'/4;
v = [1 2 1]/4;
sep = conv2(u, v, I, 'same');
max(abs(sep - conv2(I, u*v, 'same')), [], 'all')

V = rand(20, 20, 20);
k = ones(3, 3, 3) / 27;
Vs = convn(V, k, 'same');
size(Vs)
std(V(:)) > std(Vs(:))

b = 1/4 * ones(1, 4);
x = [1 2 3 4 5 6 7 8];
y = filter(b, 1, x)
alpha = 0.1;
smooth = filter(alpha, [1 -(1-alpha)], x)
[y1, zf] = filter(b, 1, x(1:4));
y2 = filter(b, 1, x(5:8), zf);

I = double(magic(6));
sobelX = [-1 0 1; -2 0 2; -1 0 1];
edges = filter2(sobelX, I);
size(edges)
isequal(filter2(sobelX, I, 'same'), conv2(I, rot90(sobelX, 2), 'same'))

